#!/usr/bin/env python3
"""Audit isolated SP+ component/total research outputs."""
import argparse,json
from pathlib import Path
import numpy as np,pandas as pd
ROOT=Path(__file__).resolve().parents[2]
REQ=['sp_plus_component_snapshot_audit.csv','sp_plus_component_snapshot_summary.json','sp_plus_component_targets.csv','sp_plus_component_features.csv','offense_direction_predictions.csv','offense_magnitude_predictions.csv','defense_direction_predictions.csv','defense_magnitude_predictions.csv','component_model_comparison.csv','game_total_projections.csv','total_model_comparison.csv','confidence_results.csv','holdout_2025_results.csv','game_level_audit.csv','final_selection.json','summary.json']
def main():
 ap=argparse.ArgumentParser(); ap.add_argument('--input-dir',default='data/research/sp_plus_total_movement'); a=ap.parse_args(); p=ROOT/a.input_dir; checks=[]
 def ck(n,v,d=''): checks.append({'check':n,'passed':bool(v),'detail':d})
 ck('all outputs exist',all((p/x).exists() for x in REQ),','.join(x for x in REQ if not (p/x).exists()))
 t=pd.read_csv(p/'sp_plus_component_targets.csv'); f=pd.read_csv(p/'sp_plus_component_features.csv',low_memory=False); o=pd.read_csv(p/'offense_direction_predictions.csv',low_memory=False); d=pd.read_csv(p/'defense_direction_predictions.csv',low_memory=False); g=pd.read_csv(p/'game_total_projections.csv'); c=pd.read_csv(p/'total_model_comparison.csv'); s=json.loads((p/'summary.json').read_text()); final=json.loads((p/'final_selection.json').read_text())
 e=t[t['eligibility'].astype(str).str.lower().eq('true')]; ck('adjacent snapshots only',((e['target_week']-e['current_snapshot_week'])==1).all()); ck('offense target arithmetic',np.allclose(e['next_sp_offense']-e['current_sp_offense'],e['actual_sp_off_change'],equal_nan=True)); ck('defense target arithmetic',np.allclose(e['next_sp_defense']-e['current_sp_defense'],e['actual_sp_def_change'],equal_nan=True)); ck('defense improvement sign',np.allclose(-e['actual_sp_def_change'],e['actual_defense_improvement'],equal_nan=True)); ck('game features precede target',(f['completed_week']==f['target_sp_plus_week']).all()); ck('no future component features',not any(x.startswith('next_sp') or x.startswith('actual_sp') for x in final['total_selection'].keys())); ck('component predictions OOS',o['prediction_oos'].astype(str).str.lower().eq('true').all() and d['prediction_oos'].astype(str).str.lower().eq('true').all()); ck('2025 locked',final['holdout_opened_after_selection'] and final['total_selection']['selected_without_2025']); ck('component-to-points selected without 2025',2025 not in final['total_selection']['conversion_fit_seasons']); ck('pace no look-ahead',g['component_prediction_oos'].astype(str).str.lower().eq('true').all()); ck('identical benchmark samples',c.groupby('season')['n'].nunique().max()==1); ck('lambda 0.85 reproduced',g['current_lambda_085_projection'].notna().any()); ck('opening totals timing unknown',g['timing_limitation_flag'].str.contains('TIMING-UNKNOWN',na=False).all()); ck('protected unchanged',s['protected_unchanged']); ck('publication repo clean',s['publication_repo_clean'])
 failed=[x for x in checks if not x['passed']]; out={'status':'PASSED' if not failed else 'FAILED','failed':len(failed),'checks':checks,'targets':len(t),'eligible':len(f),'game_rows':len(g)}; (p/'audit_results.json').write_text(json.dumps(out,indent=2)+'\n'); print(json.dumps(out,indent=2)); return 1 if failed else 0
if __name__=='__main__': raise SystemExit(main())
